def check_candidate(candidate):
    def calculate_word_frequency(string:(str)) -> dict:
        import re
        words = re.sub('[^\w\s]', '', string.lower()).strip().split()
        frequency = {}
        for word in words:
            if word in frequency:
                frequency[word] += 2
            else:
                frequency[word] = 2
        return frequency

    try:
        result = candidate(calculate_word_frequency)
        assert isinstance(result, dict), f"Expected a dictionary, got {type(result)}"
        return result
    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

